content_blocks.content:
/* Компонент меняется в зависимости от размера экрана */
@media (max-width: 768px) {
  .card { padding: 1rem; }
}

@media (min-width: 769px) {
  .card { padding: 2rem; }
}

/* Сначала помечаем элемент как контейнер */
.card-container {
  container-type: inline-size;  /* следим за шириной контейнера */
  /* или container-type: size;  /* следим за шириной и высотой */
  /* или container-name: card;  /* имя для ссылки в запросе */
}

/* Затем адаптируем содержимое под размер контейнера */
@container (max-width: 400px) {
  .card {
    padding: 1rem;
    font-size: 0.875rem;
    flex-direction: column;
  }
}

@container (min-width: 401px) {
  .card {
    padding: 1.5rem;
    font-size: 1rem;
    flex-direction: row;
  }
}

.sidebar {
  container-type: inline-size;   /* Только ширина (инлайн-размер) */
}

.main-content {
  container-type: size;          /* Ширина и высота (block + inline) */
}

.normal-flow {
  container-type: normal;        /* Не является контейнером (по умолчанию) */
}

.card-section {
  container-type: inline-size;
  container-name: card-section;
}

@container card-section (max-width: 500px) {
  .card { padding: 1rem; }
}

/* Только для карточек в сайдбаре */
@container sidebar (max-width: 300px) {
  .card { font-size: 0.75rem; }
}

/* Только для карточек в основном контенте */
@container main (max-width: 600px) {
  .card { font-size: 0.875rem; }
}

.card {
  container-type: inline-size;
}

.card__title {
  /* Размер шрифта зависит от ширины контейнера, а не экрана */
  font-size: clamp(1rem, 5cqw, 2rem);

  /* Отступы тоже от контейнера */
  padding: 2cqw;
}

.card__badge {
  font-size: 3cqw;
  min-width: 10cqw;
}

/* vw — от ширины экрана (одинаково везде на странице) */
.viewport-title {
  font-size: 5vw;
}

/* cqw — от ширины контейнера (разно в разных местах) */
.container-title {
  font-size: 5cqw;
}

:root {
  --fs-xs: clamp(0.75rem, 0.7rem + 0.5vw, 0.875rem);
  --fs-sm: clamp(0.875rem, 0.8rem + 0.75vw, 1rem);
  --fs-base: clamp(1rem, 0.9rem + 1vw, 1.125rem);
  --fs-lg: clamp(1.125rem, 1rem + 1.25vw, 1.5rem);
  --fs-xl: clamp(1.25rem, 1.1rem + 1.5vw, 2rem);
  --fs-2xl: clamp(1.5rem, 1.25rem + 2vw, 3rem);

  --space-xs: clamp(0.25rem, 0.5vw, 0.5rem);
  --space-sm: clamp(0.5rem, 1vw, 1rem);
  --space-md: clamp(1rem, 2vw, 1.5rem);
  --space-lg: clamp(1.5rem, 3vw, 3rem);
}

h1 { font-size: var(--fs-2xl); }
h2 { font-size: var(--fs-xl); }
p { font-size: var(--fs-base); line-height: 1.6; }

.section {
  padding-block: var(--space-lg);
}

.grid {
  display: grid;
  /* Каждая колонка минимум 200px, максимум 1fr (свободное место) */
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1rem;
}

.card-container {
  container-type: inline-size;
}

.card {
  padding: clamp(1rem, 4cqw, 2rem);
  gap: clamp(0.5rem, 2cqw, 1rem);
}

.card__title {
  font-size: clamp(1rem, 6cqw, 1.5rem);
}

.product-container {
  container-type: inline-size;
  container-name: product;
}

/* Базовый стиль — узкий контейнер (мобильный вид) */
.product-card {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding: 1rem;
  border: 1px solid oklch(0.88 0.006 285);
  border-radius: 0.75rem;
  background: white;
}

.product__media {
  aspect-ratio: 1 / 1;
  width: 100%;
  background: oklch(0.97 0.001 285);
  border-radius: 0.5rem;
  overflow: hidden;
}

.product__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.product__body {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  flex: 1;
}

.product__title {
  font-size: 1rem;
  font-weight: 600;
  margin: 0;
}

.product__text {
  font-size: 0.875rem;
  color: oklch(0.55 0.01 285);
  line-height: 1.5;
}

.product__price {
  font-size: 1.125rem;
  font-weight: 700;
  margin-top: auto;
}

.product__footer {
  display: flex;
  gap: 0.5rem;
  margin-top: auto;
}

.product__btn {
  flex: 1;
  padding: 0.625rem 1rem;
  background: oklch(0.62 0.22 264);
  color: white;
  border: none;
  border-radius: 0.5rem;
  cursor: pointer;
  font-size: 0.875rem;
  font-weight: 600;
}

/* Контейнерный брейкпоинт 1: средний контейнер — изображение слева, текст справа */
@container product (min-width: 450px) {
  .product-card {
    flex-direction: row;
    padding: 1.5rem;
  }

  .product__media {
    width: 180px;
    flex-shrink: 0;
    aspect-ratio: 1 / 1;
  }

  .product__title {
    font-size: 1.125rem;
  }

  .product__text {
    font-size: 0.9375rem;
  }
}

/* Контейнерный брейкпоинт 2: большой контейнер — полный вариант с’action справа */
@container product (min-width: 700px) {
  .product-card {
    padding: 2rem;
    gap: 2rem;
  }

  .product__media {
    width: 220px;
  }

  .product__title {
    font-size: 1.25rem;
  }

  .product__footer {
    flex-direction: row;
    align-items: center;
  }

  .product__btn {
    flex: none;
    width: auto;
    padding: 0.75rem 1.5rem;
  }
}

.admin-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  grid-template-rows: auto 1fr;
  gap: 1.5rem;
  padding: 1.5rem;
  min-height: 100vh;
}

/* Sidebar контейнер */
.sidebar {
  container-type: inline-size;
  container-name: sidebar;
  position: sticky;
  top: 1.5rem;
}

.sidebar__nav {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.sidebar__link {
  padding: 0.75rem;
  border-radius: 0.5rem;
  color: oklch(0.55 0.01 285);
  font-size: 0.875rem;
}

/* Адаптация сайдбара под свою ширину */
@container sidebar (max-width: 250px) {
  .sidebar__link {
    padding: 0.5rem;
    font-size: 0.75rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
  }

  .sidebar__link span {
    display: none;  /* Скрываем текст, остаются только иконки */
  }
}

/* Main контейнер */
.main-content {
  container-type: inline-size;
  container-name: main;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

/* Статистика — контейнерные брейкпоинты */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1rem;
  width: 100%;
}

.stat-card {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding: 1rem;
  background: oklch(0.98 0.001 285);
  border-radius: 0.75rem;
}

.stat-card h3 {
  font-size: 0.875rem;
  font-weight: 500;
  color: oklch(0.55 0.01 285);
  margin: 0;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: oklch(0.21 0.006 285);
}

/* Узкий контейнер — компактная статистика */
@container main (max-width: 600px) {
  .stats-grid {
    grid-template-columns: 1fr;
  }

  .stat-card {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
  }

  .stat-card h3 {
    font-size: 0.8125rem;
  }

  .stat-value {
    font-size: 1.125rem;
  }
}

/* Средний контейнер — две колонки */
@container main (min-width: 601px) and (max-width: 1000px) {
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Широкий контейнер — три колонки */
@container main (min-width: 1001px) {
  .stats-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* Таблица — горизонтальная прокрутка на узких контейнерах */
.table-section {
  overflow-x: auto;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 600px;  /* Таблица не сжимается ниже 600px */
}

.data-table th,
.data-table td {
  padding: 0.75rem 1rem;
  text-align: left;
  border-bottom: 1px solid oklch(0.88 0.006 285);
}

/* Адаптив таблицы под контейнер main */
@container main (max-width: 700px) {
  .data-table {
    font-size: 0.8125rem;
  }

  .data-table th,
  .data-table td {
    padding: 0.5rem 0.75rem;
  }
}

/* Mobile layout для всей страницы */
@media (max-width: 767px) {
  .admin-layout {
    grid-template-columns: 1fr;
    grid-template-areas:
      "main"
      "sidebar";
  }

  .sidebar {
    position: static;
    order: 2;
  }

  .main-content {
    order: 1;
  }
}

.card {
  padding: 1rem;
}

/* Современные браузеры — контейнерные запросы */
@container (min-width: 400px) {
  .card { padding: 2rem; }
}

/* Старые браузеры — медиа-запрос как fallback */
@media (min-width: 768px) {
  .card { padding: 2rem; }
}
